import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals, lineTotal, lineDiscount, lineVAT } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

// Helper to create and issue an invoice for a specific customer
function createAndIssueInvoice(customerId, issueDate, sku = 'DES-HOUR', qty = 1, terms = 'NET30') {
  const draftResult = createInvoice({
    customerId,
    issueDate,
    lines: [{ sku, qty }],
    terms,
  });
  assert.equal(draftResult.ok, true);
  const issuedResult = issueInvoice(draftResult.value, []);
  assert.equal(issuedResult.ok, true);
  return issuedResult.value;
}

test('overdueInvoices returns empty list for empty invoices', () => {
  const result = overdueInvoices([], '2026-10-07');

  assert.equal(result.length, 0);
});

test('overdueInvoices returns empty list when no invoices are overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-10-07', 'DES-HOUR', 1, 'NET30');

  const result = overdueInvoices([invoice], '2026-10-30');

  assert.equal(result.length, 0);
});

test('overdueInvoices includes issued invoices past due date', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-10-01', 'DES-HOUR', 1, 'NET14');

  const result = overdueInvoices([invoice], '2026-10-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, invoice.number);
});

test('overdueInvoices includes partially_paid invoices past due date', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-10-01', 'DES-HOUR', 5, 'NET14');
  const payment = recordPayment(invoice, { amount: 10000, date: '2026-10-08' });
  assert.equal(payment.ok, true);

  const result = overdueInvoices([payment.value], '2026-10-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, invoice.number);
});

test('overdueInvoices excludes draft invoices', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.equal(draftResult.ok, true);

  const result = overdueInvoices([draftResult.value], '2026-10-20');

  assert.equal(result.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-10-01', 'DES-HOUR', 1, 'NET14');
  const totals = invoiceTotals(invoice);
  const payment = recordPayment(invoice, { amount: totals.total, date: '2026-10-08' });
